// A Hungarian summary of a rule set for the review screen, generated by code so it always says
// what the engine will compute (the extraction never writes UI text). Pure.

import { describeFormula } from "./expr";
import type { Gate, PostStep, RuleComponent, SubjectRules } from "./types";

export interface RulesSection {
  title: string;
  lines: string[];
}

const ON_FAIL: Record<Gate["onFail"], string> = { none: "nincs jegy", fail: "elégtelen" };
const PICK: Record<string, string> = {
  worse: "a rosszabbat váltja ki",
  failed: "a sikertelent váltja ki",
  choose: "a választottat váltja ki",
};
const n = (v: number) => String(v).replace(".", ",");

function componentLine(c: RuleComponent): string {
  switch (c.kind) {
    case "attendance":
      return c.limit
        ? `${c.label}: legfeljebb ${c.limit.maxAbsences} hiányzás (${c.limit.countExcused ? "az igazolt is számít" : "csak az igazolatlan számít"}), fölötte ${ON_FAIL[c.limit.onExceed]}`
        : `${c.label}: rögzíted az alkalmakat`;
    case "exam": {
      if (c.scale.kind === "grade") return `${c.label}: jeggyel (1–5)${c.scale.passAt && c.scale.passAt !== 2 ? `, legalább ${c.scale.passAt}-es kell` : ""}`;
      const parts = c.scale.parts?.length ? `; részei: ${c.scale.parts.map((p) => `${p.label} ${n(p.max)}${p.passAt !== undefined ? ` (min. ${n(p.passAt)})` : ""}`).join(", ")}` : "";
      return `${c.label}: ${n(c.scale.max)} pont${c.scale.passAt !== undefined ? `, legalább ${n(c.scale.passAt)} ponttal sikeres` : ""}${parts}`;
    }
    case "assignment":
      return `${c.label}: ${c.outcomes.map((o) => `${o.label.toLowerCase()} ${n(o.points)} pont`).join(", ")}`;
    case "series": {
      const s = c.scoring;
      if (s.kind === "plusMinus") return `${c.label}: ${c.count} alkalom, pluszt vagy mínuszt kapsz`;
      if (s.kind === "percent") {
        return `${c.label}: ${c.count} db, legalább ${s.passAt}%-kal teljesített${s.attempts ? `, ${s.attempts} próbálkozás` : ""}${s.onTimeOnly ? ", csak határidőre számít" : ""}`;
      }
      const parts = s.parts?.length ? ` (${s.parts.map((p) => `${p.label} ${n(p.max)}`).join(" + ")})` : "";
      return `${c.label}: ${c.count} × ${n(s.max)} pont${parts}`;
    }
    case "bonus":
      return `${c.label}${c.cap !== undefined ? `: legfeljebb ${n(c.cap)}` : ""}`;
  }
}

export function describeRules(rules: SubjectRules): RulesSection[] {
  const labels: Record<string, string> = {};
  for (const c of rules.components) {
    labels[c.id] = c.label;
    const parts = c.kind === "exam" && c.scale.kind === "points" ? c.scale.parts : c.kind === "series" && c.scoring.kind === "points" ? c.scoring.parts : undefined;
    for (const p of parts ?? []) labels[`${c.id}.${p.id}`] = `${c.label} (${p.label.toLowerCase()})`;
  }
  for (const r of rules.retakes) labels[r.id] = r.label;
  for (const d of rules.derived) labels[d.id] = d.label;
  for (const t of rules.tables) {
    const owner = rules.components.find((c) => t.id === `${c.id}tabla` || t.id.startsWith(c.id));
    labels[t.id] = t.id === "jegy" ? "a jegytáblázat" : owner ? `${owner.label} táblázata` : `a(z) ${t.id}`;
  }
  for (const o of rules.outcomes) labels[o.id] = o.label.toLowerCase().replace(/ jegy$/, "");
  const f = (src: string) => describeFormula(src, labels).replace(/(táblázat|táblázata) táblázat szerint/g, "$1 szerint");
  const post = (p: PostStep) => (p.kind === "cap" ? `legfeljebb ${p.max}` : `${p.delta > 0 ? "+" : "−"}${Math.abs(p.delta)} jegy, ha ${f(p.when)}`);

  const sections: RulesSection[] = [{ title: "Összetevők", lines: rules.components.map(componentLine) }];
  if (rules.retakes.length) {
    sections.push({
      title: "Javítás",
      lines: rules.retakes.map(
        (r) =>
          `${r.label} (${r.targets.map((t) => labels[t] ?? t).join(", ")}): ${PICK[r.pick]}, ${r.mode === "replace" ? "akkor is, ha rosszabb" : "csak ha jobb"}${r.eligible ? `; feltétel: ${f(r.eligible)}` : ""}`
      ),
    });
  }
  const calc = [
    ...rules.derived.map((d) => `${d.label}: ${f(d.expr)}`),
    ...rules.tables.map((t) => {
      const rows = t.rows.map((row) => `≥ ${n(row.min)}: ${row.value}`);
      const name = labels[t.id].replace(/^a /, "");
      return `${name.charAt(0).toUpperCase()}${name.slice(1)}: ${rows.join(", ")}`;
    }),
  ];
  if (calc.length) sections.push({ title: "Számítás", lines: calc });
  for (const o of rules.outcomes) {
    const lines: string[] = [];
    for (const g of o.gates ?? []) lines.push(`Feltétel: ${g.label} (különben ${ON_FAIL[g.onFail]})`);
    for (const p of o.paths) {
      const head = o.paths.length > 1 ? `${p.label}${p.when ? ` (ha ${f(p.when)})` : ""}: ` : "";
      const gates = (p.gates ?? []).map((g) => `${g.label} (különben ${ON_FAIL[g.onFail]})`);
      lines.push(`${head}${gates.length ? `Feltétel: ${gates.join("; ")}. ` : ""}Jegy: ${f(p.grade)}${p.post?.length ? `; ${p.post.map(post).join("; ")}` : ""}`);
    }
    if (o.paths.length > 1) lines.push(o.select === "best" ? "A legjobb érvényes út számít." : "Az első érvényes út számít.");
    sections.push({ title: o.label, lines });
  }
  return sections;
}
